  /**
   * Methods under test:
   * <ul>
   *   <li>{@link ObjectDefinition#getDefaultInstance()}
   *   <li>{@link ObjectDefinition#getDescriptor()}
   *   <li>{@link ObjectDefinition#newBuilder()}
   *   <li>{@link ObjectDefinition#newBuilder(ObjectDefinition)}
   *   <li>{@link ObjectDefinition#newBuilderForType()}
   *   <li>{@link ObjectDefinition#toBuilder()}
   *   <li>{@link ObjectDefinition#getCustomOrBuilder()}
   *   <li>{@link ObjectDefinition#getDataOrBuilder()}
   *   <li>{@link ObjectDefinition#getFileOrBuilder()}
   *   <li>{@link ObjectDefinition#getFlowOrBuilder()}
   *   <li>{@link ObjectDefinition#getJobOrBuilder()}
   *   <li>{@link ObjectDefinition#getModelOrBuilder()}
   *   <li>{@link ObjectDefinition#getObjectTypeValue()}
   *   <li>{@link ObjectDefinition#getParserForType()}
   *   <li>{@link ObjectDefinition#getResultOrBuilder()}
   *   <li>{@link ObjectDefinition#getSchemaOrBuilder()}
   *   <li>{@link ObjectDefinition#getStorageOrBuilder()}
   * </ul>
   */
  @Test
  void testGettersAndSetters() {
    // Arrange and Act
    ObjectDefinition actualDefaultInstance = ObjectDefinition.getDefaultInstance();
    ObjectDefinition actualDefaultInstance2 = actualDefaultInstance.getDefaultInstance();
    Descriptors.Descriptor actualDescriptor = actualDefaultInstance.getDescriptor();
    actualDefaultInstance.newBuilder();
    ObjectDefinition prototype = ObjectDefinition.getDefaultInstance();
    actualDefaultInstance.newBuilder(prototype);
    actualDefaultInstance.newBuilderForType();
    actualDefaultInstance.toBuilder();
    CustomDefinitionOrBuilder actualCustomOrBuilder = actualDefaultInstance.getCustomOrBuilder();
    DataDefinitionOrBuilder actualDataOrBuilder = actualDefaultInstance.getDataOrBuilder();
    FileDefinitionOrBuilder actualFileOrBuilder = actualDefaultInstance.getFileOrBuilder();
    FlowDefinitionOrBuilder actualFlowOrBuilder = actualDefaultInstance.getFlowOrBuilder();
    JobDefinitionOrBuilder actualJobOrBuilder = actualDefaultInstance.getJobOrBuilder();
    ModelDefinitionOrBuilder actualModelOrBuilder = actualDefaultInstance.getModelOrBuilder();
    int actualObjectTypeValue = actualDefaultInstance.getObjectTypeValue();
    actualDefaultInstance.getParserForType();
    ResultDefinitionOrBuilder actualResultOrBuilder = actualDefaultInstance.getResultOrBuilder();
    SchemaDefinitionOrBuilder actualSchemaOrBuilder = actualDefaultInstance.getSchemaOrBuilder();
    StorageDefinitionOrBuilder actualStorageOrBuilder = actualDefaultInstance.getStorageOrBuilder();

    // Assert
    UnknownFieldSet unknownFields = actualDefaultInstance.getUnknownFields();
    assertEquals(0, unknownFields.getSerializedSize());
    assertEquals(0, unknownFields.getSerializedSizeAsMessageSet());
    assertEquals(0, actualObjectTypeValue);
    assertTrue(unknownFields.isEmpty());
    assertTrue(unknownFields.isInitialized());
    assertSame(actualDefaultInstance.getDescriptorForType(), actualDescriptor);
    assertSame(actualDefaultInstance.getCustom(), actualCustomOrBuilder);
    assertSame(actualDefaultInstance.getData(), actualDataOrBuilder);
    assertSame(actualDefaultInstance.getFile(), actualFileOrBuilder);
    assertSame(actualDefaultInstance.getFlow(), actualFlowOrBuilder);
    assertSame(actualDefaultInstance.getJob(), actualJobOrBuilder);
    assertSame(actualDefaultInstance.getModel(), actualModelOrBuilder);
    assertSame(actualDefaultInstance.getResult(), actualResultOrBuilder);
    assertSame(actualDefaultInstance.getSchema(), actualSchemaOrBuilder);
    assertSame(actualDefaultInstance.getStorage(), actualStorageOrBuilder);
    assertSame(prototype, actualDefaultInstance2);
  }
